import { useContext } from "react";
import { AppContext } from "../../context/AppContext";

export default function UserOrders() {
  const { orders } = useContext(AppContext);

  return (
    <div style={{ marginTop: "12px" }}>
      <h3 className="section-title">Recent Orders</h3>
      <div className="orders-list">
        {orders.length === 0 && (
          <span className="small-text">No orders placed yet.</span>
        )}

        {orders.map(order => (
          <div key={order.id} className="order-item">
            <div>
              <b>{order.id}</b> — {order.items.map(i => `${i.name} x${i.qty}`).join(", ")}
              <div className="small-text">₹{order.amount}</div>
            </div>
            <span className={`order-chip order-chip-${order.status.toLowerCase()}`}>
              {order.status}
            </span>
          </div>
        ))}
      </div>
    </div>
  );
}
